INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('d7a044ca-cc0d-4ee4-8452-1241ed2c315c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'bbd41fba-581f-4311-aab4-7a68e6d62cc5', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रैदास नाम से विख्यात संत रविदास का जन्म काशी (वाराणसी) में हुआ। उनका जीवन-काल 15वीं शताब््‍ददी (सन् 1388–1518) माना जाता है। रैदास संत कवियों में गिने जाते हैं। उन््होंने बाह्य आडंबरों का खंडन कर मन की शुद्धता और आंतरिक भक्‍तति को ही सच्चा धर््म माना है। रैदास ने अपनी काव्य-रचनाओं में सरल, व्यावहारिक ब्रजभाषा का प्रयोग किया है, जिसमें अवधी, राजस््थानी, खड़ी बोली और उर््ददू-फारसी के शब््दों का भी मिश्रण है। उनकी सरल ब्रज भाषा में लिखी भक्‍तति रचनाएँ आदि श्री गुरु ग्रंथ साहिब जी में शामिल हैं और वे आज भी समानता, प्रेम और भाईचारे का संदेश देती हैं। उनकी रचनाएँ रैदास बानी में संकलित हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-508Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('94315d58-4057-4437-80bb-3a040431515f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'bbd41fba-581f-4311-aab4-7a68e6d62cc5', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यहाँ रैदास के दो पद लिए गए हैं। पहले पद में बताया गया है कि जैसे चंंदन-पानी, दीपक-बाती, मोती-धागा और बादल-मोर का संंबंंध अटूट होता है, वैसे ही भक्त से उसके आराध्य अलग नहीं हो सकते। इस पद में अनन्य भक््‍तति और आराध्य के प्रति समर्पण का भाव प्रकट होता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-508Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('428d4911-fdad-4042-a525-09e34839d721', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'bbd41fba-581f-4311-aab4-7a68e6d62cc5', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूसरे पद में भी आराध्य से भक्त का अटूट नाता व्यक्त किया गया है। वह तीर््थ और व्रत छोड़ सकता है, पर प्रभु-चरणों की भक््‍तति नहीं। यह पद निष््‍ठा, विश्वास और अडिग भक््‍तति को व््ययंजित करता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-508Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
