  ('05cc4d37-53f4-4684-a772-1df74c2bf5bd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'bbd41fba-581f-4311-aab4-7a68e6d62cc5', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी सरल ब्रज भाषा में लिखी भक्‍तति रचनाएँ आदि श्री गुरु ग्रंथ साहिब जी में शामिल हैं और वे आज भी समानता, प्रेम और भाईचारे का संदेश देती हैं। उनकी रचनाएँ रैदास बानी में संकलित हैं। यहाँ रैदास के दो पद लिए गए हैं। पहले पद में बताया गया है कि जैसे चंंदन-पानी, दीपक-बाती, मोती-धागा और बादल-मोर का संंबंंध अटूट होता है, वैसे ही भक्त से उसके आराध्य अलग नहीं हो सकते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-508Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('a55e32ac-ceb8-4245-a2c8-c4cee8048628', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'bbd41fba-581f-4311-aab4-7a68e6d62cc5', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अब कैसे छूटै राम रट लागी। प्रभु जी तुम चंदन हम पानी, जाकी अंग-अंग बास समानी। प्रभु जी तुम घन बन, हम मोरा, जैसे चितवत चंद चकोरा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-508Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fded10c3-1244-447d-a09d-7ef58e74dbbd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'bbd41fba-581f-4311-aab4-7a68e6d62cc5', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रभु जी तुम दीपक, हम बाती, जाकी जोति बरै दिन राती। प्रभु जी तुम मोती, हम धागा, जैसे सोने मिलत सुहागा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-508Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c3b3cbff-1497-4d0e-9817-d22b502f44da', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'bbd41fba-581f-4311-aab4-7a68e6d62cc5', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रभु जी तुम स्वामी, हम दासा, ऐसी भगति करै रैदासा। जो तुम तोरौ राम मैं नहिं तोरौ, तुम सौ तोरि कवन सौं जोरौ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-508Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
