  ('71541f83-a27b-4503-a83b-a5afb43ae4da', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', 'bbd41fba-581f-4311-aab4-7a68e6d62cc5', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं अपनो मन हरि से जोरौ, हरि सो जोरि सबन सो तोरों। सबही पहर तुम्हारी आसा, मन क्रम वचन कहै रैदासा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-40-508Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
